ControlPropertyState.AutoRuleBindingString:
UpdateContext({varShowDeleteReceiptDialog: false});
If(
    !IsBlank(varDeleteReceiptId),
    IfError(
        Patch(
            'Expense Mobile Unattached Document Entity (mserp)',
            LookUp('Expense Mobile Unattached Document Entity (mserp)', EntRecId = varDeleteReceiptId),
            {
                ExpTransNumber: Blank()
            }
        ),
        Notify(
            Substitute(
                Match(FirstError.Details.HttpResponse, """message"":""([^""]*)""").FullMatch,
                """message"":",
                ""
            ),
            NotificationType.Error,
            gblParams.notificationTime
        )
    );
    // Refresh receipts collection
    ClearCollect(
        colAttachedReceipts,
        SortByColumns(
            Filter(
                'Expense Mobile Unattached Document Entity (mserp)',
                ExpTransNumber = varSelectedExpenseDoc.'Expense transaction number (mserp_exptransnumber)'
            ),
            "CreatingDateTime",
            SortOrder.Descending
        )
    );
    // Update AttachedReceiptId (first receipt or blank)
    If(
        !IsEmpty(colAttachedReceipts),
        Patch(
            'Expense lines (mserp)',
            varSelectedExpenseDoc,
            {
                AttachedReceiptId: First(colAttachedReceipts).EntRecId
            }
        ),
        Patch(
            'Expense lines (mserp)',
            varSelectedExpenseDoc,
            {
                AttachedReceiptId: Blank()
            }
        )
    );
    // Update varReceiptImage for backward compatibility
    Set(
        varReceiptImage,
        If(
            !IsEmpty(colAttachedReceipts),
            First(colAttachedReceipts).CapturedDocument,
            Blank()
        )
    );
    Set(
        varFileFormat,
        If(
            !IsEmpty(colAttachedReceipts),
            First(colAttachedReceipts).FileExtension,
            Blank()
        )
    );
    Notify(
        GlobalLabels.Labels.'15062:LocalizedName,msdyn_ReceiptDetachedSuccessfullyLabel',
        NotificationType.Success,
        gblParams.notificationTime
    );
    UpdateContext({varDeleteReceiptId: Blank()})
)

Navigate('Expenses - Capture Receipt Screen', ScreenTransition.None);
UpdateContext(
    {
        varOnSelectTriggered: false,
        varOnShowFields:false,
        varOnChangeTriggered:false
    }
)

Set(
    varSelectedReceiptForView,
    ThisItem.EntRecId
);
Set(
    varReceiptImage,
    ThisItem.CapturedDocument
);
Set(
    varFileFormat,
    ThisItem.FileExtension
);
Navigate('Expenses - View Receipt Screen', ScreenTransition.None, {varViewOnly : false})
